schemaVersion: "2"
kind: mixin
name: claude-powerline
version: "1.0.0"
displayName: claude-powerline statusline
description: Installs @owloops/claude-powerline and wires it into the sandbox statusLine.

requires:
  agent: claude

permissions:
  network:
    allow:
      - registry.npmjs.org

setup:
  install:
    - command: npm install -g @owloops/claude-powerline@latest
      user: "0"
      description: Install the claude-powerline binary globally

    # Belt-and-braces alongside setup.startup below: docker/sbx-releases#189 —
    # a kit's setup.startup can silently fail to fire when stacked with other
    # --kit flags, with no error output. setup.install is the phase that's
    # actually reliable when kits are combined, so the merge happens here too
    # (inline, since setup.install runs before setup.files exists yet).
    - command: |
        node <<'EOF'
        const { readFileSync, writeFileSync, mkdirSync } = require("node:fs");
        const { dirname, join } = require("node:path");
        const p = join(process.env.HOME, ".claude", "settings.json");
        let s = {};
        try { s = JSON.parse(readFileSync(p, "utf8")); } catch {}
        s.statusLine = { type: "command", command: "claude-powerline" };
        mkdirSync(dirname(p), { recursive: true });
        writeFileSync(p, JSON.stringify(s, null, 2) + "\n");
        console.log("statusLine ->", s.statusLine.command);
        EOF
      user: "1000"
      description: Merge statusLine at install time, in case setup.startup never fires

  files:
    - path: /home/agent/.local/bin/wire-powerline.mjs
      mode: "0755"
      description: Merge statusLine into the agent settings without clobbering them
      content: |
        import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
        import { dirname, join } from "node:path";
        const p = join(process.env.HOME, ".claude", "settings.json");
        let s = {};
        try { s = JSON.parse(readFileSync(p, "utf8")); } catch {}
        s.statusLine = { type: "command", command: "claude-powerline" };
        mkdirSync(dirname(p), { recursive: true });
        writeFileSync(p, JSON.stringify(s, null, 2) + "\n");
        console.log("statusLine ->", s.statusLine.command);

  startup:
    - command: ["node", "/home/agent/.local/bin/wire-powerline.mjs"]
      user: "1000"
      description: Wire the statusline on every start

